mapper.update:
UPDATE material SET lifecycle_state = 'DELETING'
WHERE id = #{materialId} AND lifecycle_generation = #{lifecycleGeneration}
  AND lifecycle_state IN ('DELETE_PENDING', 'DELETING')

mapper.delete:
DELETE ce FROM citation_evidence ce
JOIN material_version v ON v.id = ce.version_id
WHERE v.material_id = #{materialId}

mapper.update:
UPDATE material_content_blob blob
JOIN material_version owned_version ON owned_version.content_blob_id = blob.id
SET blob.status = 'DELETE_PENDING'
WHERE owned_version.material_id = #{materialId}
  AND NOT EXISTS (
      SELECT 1 FROM material_version other
      WHERE other.content_blob_id = blob.id AND other.material_id <> #{materialId}
  )

UPDATE retrieval_chunk_vector_projection projection
JOIN retrieval_chunk chunk ON chunk.id = projection.retrieval_chunk_id
JOIN material_version v ON v.id = chunk.version_id
SET projection.provider_deleted_at = #{deletedAt}
WHERE v.material_id = #{materialId} AND projection.index_name = #{indexName}
  AND projection.provider_deleted_at IS NULL

UPDATE deletion_task
SET stage = #{task.stage}, status = #{task.status}, attempt = #{task.attempt},
    not_before = #{task.notBefore}, lease_owner = #{task.leaseOwner},
    lease_until = #{task.leaseUntil}, fence_token = #{task.fenceToken}, error_code = #{task.errorCode}
WHERE id = #{task.id} AND stage = #{expectedStage} AND status = 'RUNNING'
  AND fence_token = #{expectedFenceToken}

UPDATE deletion_task
SET status = 'RETRY', lease_owner = NULL, lease_until = NULL,
    not_before = #{now}, error_code = 'LEASE_EXPIRED'
WHERE status = 'RUNNING' AND lease_until <= #{now}
ORDER BY lease_until LIMIT #{limit}
